import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Button, Navbar, Nav, Form, InputGroup, Badge, Modal, Table, Alert, Spinner, Toast } from 'react-bootstrap';
import 'bootstrap/dist/css/bootstrap.min.css';
import './App.css';
import AdminPanel from './AdminPanel';
import PaymentModal from './PaymentModal';

const API_URL = 'http://localhost:5000/api';

// Format Indian Rupee function
const formatIndianRupee = (amount) => {
  return new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0
  }).format(amount);
};

// Error Notification Modal Component
const ErrorNotificationModal = ({ show, onClose, message, title = "Error" }) => {
  if (!show) return null;
  
  return (
    <div className="error-modal-overlay" onClick={onClose}>
      <div className="error-modal-content" onClick={(e) => e.stopPropagation()}>
        <div className="error-icon">
          <i className="bi bi-exclamation-triangle-fill"></i>
        </div>
        <h3>{title}</h3>
        <p>{message}</p>
        <button className="error-close-btn" onClick={onClose}>
          <i className="bi bi-check-circle"></i> Got it
        </button>
      </div>
    </div>
  );
};

// Product Detail Modal Component
const ProductDetailModal = ({ show, onClose, product, onAddToCart, onBuyNow }) => {
  const [quantity, setQuantity] = useState(1);
  
  if (!show || !product) return null;
  
  const totalPrice = product.price * quantity;
  
  return (
    <div className="product-detail-overlay" onClick={onClose}>
      <div className="product-detail-modal" onClick={(e) => e.stopPropagation()}>
        <button className="modal-close-btn" onClick={onClose}>✕</button>
        
        <div className="product-detail-content">
          <div className="product-detail-image">
            <img src={product.image} alt={product.name} />
            {product.stock < 20 && (
              <span className="stock-warning">⚠️ Only {product.stock} left!</span>
            )}
          </div>
          
          <div className="product-detail-info">
            <div className="product-brand-badge">
              <span className="brand-name">{product.brand}</span>
              <span className="category-tag">{product.category}</span>
            </div>
            
            <h2 className="product-detail-name">{product.name}</h2>
            
            <div className="product-detail-rating">
              {'★'.repeat(Math.floor(product.rating))}
              {'☆'.repeat(5 - Math.floor(product.rating))}
              <span>({product.rating} out of 5)</span>
            </div>
            
            <p className="product-detail-description">{product.description}</p>
            
            <div className="price-section">
              <div className="current-price">{formatIndianRupee(product.price)}</div>
              <div className="tax-info">Inclusive of all taxes</div>
            </div>
            
            <div className="quantity-selector">
              <label>Quantity:</label>
              <div className="quantity-controls">
                <button onClick={() => setQuantity(Math.max(1, quantity - 1))}>-</button>
                <span>{quantity}</span>
                <button onClick={() => setQuantity(Math.min(product.stock, quantity + 1))}>+</button>
              </div>
              <span className="stock-info">{product.stock} items available</span>
            </div>
            
            <div className="total-price">
              <span>Total Amount:</span>
              <span>{formatIndianRupee(totalPrice)}</span>
            </div>
            
            <div className="action-buttons">
              <button 
                className="add-to-cart-btn-detail"
                onClick={() => {
                  onAddToCart(product, quantity);
                  onClose();
                }}
              >
                <i className="bi bi-cart-plus"></i> Add to Cart
              </button>
              <button 
                className="buy-now-btn"
                onClick={() => onBuyNow(product, quantity)}
              >
                <i className="bi bi-lightning-charge"></i> Buy Now
              </button>
            </div>
            
            <div className="delivery-info">
              <div className="info-item">
                <i className="bi bi-truck"></i>
                <span>Free delivery on orders above ₹50,000</span>
              </div>
              <div className="info-item">
                <i className="bi bi-arrow-return-left"></i>
                <span>30 days easy returns</span>
              </div>
              <div className="info-item">
                <i className="bi bi-shield-check"></i>
                <span>Secure payment</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

// Order Confirmation Modal Component
const OrderConfirmationModal = ({ show, onClose, orderDetails }) => {
  if (!show || !orderDetails) return null;
  
  return (
    <div className="order-confirmation-overlay" onClick={onClose}>
      <div className="order-confirmation-modal" onClick={(e) => e.stopPropagation()}>
        <div className="confirmation-header">
          <div className="success-animation">
            <div className="checkmark-circle">
              <div className="checkmark"></div>
            </div>
          </div>
          <h2>🎉 Order Confirmed!</h2>
          <p>Thank you for shopping with ShopHub India</p>
        </div>
        
        <div className="confirmation-body">
          <div className="order-details-card">
            <div className="detail-row">
              <span className="detail-label">Order ID:</span>
              <span className="detail-value">{orderDetails.orderId}</span>
            </div>
            <div className="detail-row">
              <span className="detail-label">Order Date:</span>
              <span className="detail-value">{orderDetails.date}</span>
            </div>
            <div className="detail-row">
              <span className="detail-label">Total Amount:</span>
              <span className="detail-value highlight">{orderDetails.total}</span>
            </div>
            <div className="detail-row">
              <span className="detail-label">Payment Method:</span>
              <span className="detail-value">{orderDetails.paymentMethod}</span>
            </div>
            <div className="detail-row">
              <span className="detail-label">Shipping Address:</span>
              <span className="detail-value">{orderDetails.shippingAddress}</span>
            </div>
          </div>
          
          <div className="order-items">
            <h4>📦 Order Summary</h4>
            {orderDetails.items?.map((item, idx) => (
              <div key={idx} className="order-item">
                <span>{item.name} x {item.quantity}</span>
                <span>{formatIndianRupee(item.price * item.quantity)}</span>
              </div>
            ))}
            <div className="order-total">
              <strong>Total</strong>
              <strong>{orderDetails.total}</strong>
            </div>
          </div>
        </div>
        
        <div className="confirmation-footer">
          <p className="delivery-note">
            <i className="bi bi-truck"></i> Estimated Delivery: 3-5 business days
          </p>
          <p className="tracking-note">
            <i className="bi bi-envelope"></i> Order details sent to your email
          </p>
          <button className="continue-shopping-btn" onClick={onClose}>
            Continue Shopping <i className="bi bi-arrow-right"></i>
          </button>
        </div>
      </div>
    </div>
  );
};

// Notification Helper Functions
const showBrowserNotification = (title, body, icon = 'https://cdn-icons-png.flaticon.com/512/2838/2838912.png') => {
  if (Notification.permission === 'granted') {
    new Notification(title, { body, icon });
  } else if (Notification.permission !== 'denied') {
    Notification.requestPermission().then(permission => {
      if (permission === 'granted') {
        new Notification(title, { body, icon });
      }
    });
  }
};

// Play notification sound
const playNotificationSound = () => {
  const audio = new Audio('https://www.soundjay.com/misc/sounds/bell-ringing-05.mp3');
  audio.play().catch(e => console.log('Audio play failed:', e));
};

function App() {
  const [products, setProducts] = useState([]);
  const [cart, setCart] = useState([]);
  const [user, setUser] = useState(null);
  const [users, setUsers] = useState([]);
  const [wishlist, setWishlist] = useState([]);
  const [showLogin, setShowLogin] = useState(false);
  const [showCart, setShowCart] = useState(false);
  const [showCheckout, setShowCheckout] = useState(false);
  const [showWishlist, setShowWishlist] = useState(false);
  const [showAdmin, setShowAdmin] = useState(false);
  const [showReview, setShowReview] = useState(false);
  const [showPayment, setShowPayment] = useState(false);
  const [showOrderConfirmation, setShowOrderConfirmation] = useState(false);
  const [showProductDetail, setShowProductDetail] = useState(false);
  const [showErrorModal, setShowErrorModal] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');
  const [confirmedOrder, setConfirmedOrder] = useState(null);
  const [selectedProductDetail, setSelectedProductDetail] = useState(null);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [reviewText, setReviewText] = useState('');
  const [reviewRating, setReviewRating] = useState(5);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [isLogin, setIsLogin] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [loading, setLoading] = useState(true);
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [notificationPermission, setNotificationPermission] = useState(false);
  const [showPromoBanner, setShowPromoBanner] = useState(true);
  const [cartReminder, setCartReminder] = useState(false);

  const [shippingDetails, setShippingDetails] = useState({
    fullName: '',
    address: '',
    city: '',
    state: '',
    pincode: '',
    phone: '',
    paymentMethod: 'cod'
  });

  // Load users from localStorage
  useEffect(() => {
    const savedUsers = JSON.parse(localStorage.getItem('app_users') || '[]');
    // Add default admin if no users exist
    if (savedUsers.length === 0) {
      const defaultUsers = [
        { id: 1, name: 'Panku Chauhan (Admin)', email: 'pankuchauhan35@gmail.com', password: '@panku2003', isAdmin: true }
      ];
      localStorage.setItem('app_users', JSON.stringify(defaultUsers));
      setUsers(defaultUsers);
    } else {
      setUsers(savedUsers);
    }
  }, []);

  // All products data
  const allProducts = [
    { id: 1, name: "Apple AirPods Pro", price: 24999, description: "Active Noise Cancellation, Transparency mode, Spatial audio, MagSafe charging case. Perfect for immersive sound experience.", category: "Electronics", image: "https://images.unsplash.com/photo-1588423771073-b8903fbb85b5?w=400", stock: 25, brand: "Apple", rating: 4.8 },
    { id: 2, name: "Sony WH-1000XM5", price: 29999, description: "Industry-leading noise cancellation, 30-hour battery life, Premium sound quality, LDAC support, comfortable fit.", category: "Electronics", image: "https://images.unsplash.com/photo-1618366712010-f4ae9c647dcb?w=400", stock: 15, brand: "Sony", rating: 4.9 },
    { id: 3, name: "iPhone 15 Pro", price: 134900, description: "A17 Pro chip, Titanium design, 48MP main camera with 24MP default, USB-C, Action button, 5G ready.", category: "Electronics", image: "https://images.unsplash.com/photo-1696446701796-da61225697cc?w=400", stock: 10, brand: "Apple", rating: 4.9 },
    { id: 4, name: "Nike Air Max", price: 12999, description: "Comfortable running shoes with Air Max cushioning, breathable mesh upper, durable rubber sole, perfect for daily runs.", category: "Clothing", image: "https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=400", stock: 40, brand: "Nike", rating: 4.6 },
    { id: 5, name: "Levi's Jeans", price: 3999, description: "Premium denim jeans, slim fit, comfortable cotton blend, 5-pocket styling, perfect for casual wear.", category: "Clothing", image: "https://images.unsplash.com/photo-1541099649105-f69ad21f3246?w=400", stock: 50, brand: "Levi's", rating: 4.5 },
    { id: 6, name: "Fossil Gen 6 Watch", price: 22999, description: "Smart watch with Wear OS, heart rate tracking, GPS, AMOLED display, 1GB RAM, fast charging.", category: "Accessories", image: "https://images.unsplash.com/photo-1524805444758-089113d48a6d?w=400", stock: 20, brand: "Fossil", rating: 4.7 },
    { id: 7, name: "Titan Analog Watch", price: 8999, description: "Elegant analog watch with stainless steel strap, water resistant, mineral glass, 2-year warranty.", category: "Accessories", image: "https://images.unsplash.com/photo-1522312346375-d1a52e2b99b3?w=400", stock: 30, brand: "Titan", rating: 4.5 },
    { id: 8, name: "MacBook Pro M3", price: 169900, description: "M3 chip with 8-core CPU and 10-core GPU, 14-inch Liquid Retina XDR display, 18GB RAM, 512GB SSD.", category: "Electronics", image: "https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=400", stock: 8, brand: "Apple", rating: 4.9 },
    { id: 9, name: "Puma T-Shirt", price: 1499, description: "Cotton blend t-shirt, regular fit, sports style, breathable fabric, available in multiple colors.", category: "Clothing", image: "https://images.unsplash.com/photo-1521572163474-6864f9cf17ab?w=400", stock: 60, brand: "Puma", rating: 4.4 },
    { id: 10, name: "Adidas Track Pant", price: 2999, description: "Comfortable track pants for daily wear, elastic waistband, side pockets, breathable fabric.", category: "Clothing", image: "https://images.unsplash.com/photo-1556906781-9a412961c28c?w=400", stock: 55, brand: "Adidas", rating: 4.5 },
    { id: 11, name: "Boat Airdopes", price: 1799, description: "Wireless earbuds with 40h battery life, ENx technology, clear voice calls, ASAP charging.", category: "Electronics", image: "https://images.unsplash.com/photo-1606220588913-b3aacb4d2f46?w=400", stock: 100, brand: "Boat", rating: 4.3 },
    { id: 12, name: "Fastrack Backpack", price: 2499, description: "Durable backpack with laptop compartment, USB charging port, multiple pockets, water resistant.", category: "Accessories", image: "https://images.unsplash.com/photo-1553062407-98eeb64c6a62?w=400", stock: 40, brand: "Fastrack", rating: 4.4 }
  ];

  // Request notification permission on load
  useEffect(() => {
    setProducts(allProducts);
    setLoading(false);
    
    const token = localStorage.getItem('token');
    const userData = JSON.parse(localStorage.getItem('user') || '{}');
    if (token && userData.id) {
      setUser(userData);
      loadWishlist(userData.id);
    }
    
    // Load cart from localStorage
    const savedCart = JSON.parse(localStorage.getItem('cart') || '[]');
    if (savedCart.length > 0) {
      setCart(savedCart);
    }
    
    // Request notification permission
    if ('Notification' in window) {
      if (Notification.permission === 'granted') {
        setNotificationPermission(true);
      } else if (Notification.permission !== 'denied') {
        Notification.requestPermission().then(permission => {
          setNotificationPermission(permission === 'granted');
        });
      }
    }
    
    // Show welcome notification after 3 seconds
    setTimeout(() => {
      if (Notification.permission === 'granted') {
        showBrowserNotification(
          '🎉 Welcome to ShopHub India!',
          'Create an account and get 10% off on your first order!',
          'https://cdn-icons-png.flaticon.com/512/2838/2838912.png'
        );
      }
    }, 3000);
    
    // Cart reminder
    const cartInterval = setInterval(() => {
      const savedCartItems = JSON.parse(localStorage.getItem('cart') || '[]');
      if (savedCartItems.length > 0 && !cartReminder && !user) {
        showBrowserNotification(
          '🛒 Don\'t forget your items!',
          `You have ${savedCartItems.length} item(s) in your cart. Complete your purchase now!`,
          'https://cdn-icons-png.flaticon.com/512/2331/2331970.png'
        );
        setCartReminder(true);
      }
    }, 30000);
    
    return () => clearInterval(cartInterval);
  }, []);

  const loadWishlist = (userId) => {
    const savedWishlist = JSON.parse(localStorage.getItem(`wishlist_${userId}`) || '[]');
    setWishlist(savedWishlist);
  };

  const saveWishlist = (userId, newWishlist) => {
    localStorage.setItem(`wishlist_${userId}`, JSON.stringify(newWishlist));
    setWishlist(newWishlist);
  };

  const toggleWishlist = (product) => {
    if (!user) {
      setErrorMessage('Please login to add items to wishlist');
      setShowErrorModal(true);
      return;
    }
    
    const exists = wishlist.some(item => item.id === product.id);
    let newWishlist;
    if (exists) {
      newWishlist = wishlist.filter(item => item.id !== product.id);
      showMessage('Removed from wishlist ❤️');
    } else {
      newWishlist = [...wishlist, product];
      showMessage('Added to wishlist ❤️');
      showBrowserNotification(
        '❤️ Added to Wishlist!',
        `${product.name} has been saved to your wishlist.`,
        product.image
      );
    }
    saveWishlist(user.id, newWishlist);
  };

  const addReview = () => {
    if (!user) {
      setErrorMessage('Please login to add review');
      setShowErrorModal(true);
      return;
    }
    
    const productReviews = JSON.parse(localStorage.getItem(`reviews_${selectedProduct.id}`) || '[]');
    productReviews.push({
      id: Date.now(),
      userName: user.name,
      rating: reviewRating,
      comment: reviewText,
      date: new Date().toISOString()
    });
    localStorage.setItem(`reviews_${selectedProduct.id}`, JSON.stringify(productReviews));
    
    showMessage('Review added successfully! ⭐');
    setShowReview(false);
    setReviewText('');
    setReviewRating(5);
  };

  const getProductReviews = (productId) => {
    return JSON.parse(localStorage.getItem(`reviews_${productId}`) || '[]');
  };

  const showMessage = (message) => {
    setToastMessage(message);
    setShowToast(true);
    setTimeout(() => setShowToast(false), 3000);
  };

  // REAL LOGIN WITH STORED USERS
  const handleLogin = (e) => {
    e.preventDefault();
    const storedUsers = JSON.parse(localStorage.getItem('app_users') || '[]');
    
    if (!isLogin) {
      // REGISTER - Create new account
      const existingUser = storedUsers.find(u => u.email === email);
      if (existingUser) {
        setErrorMessage('Email already registered! Please login.');
        setShowErrorModal(true);
        return;
      }
      
      if (!name || !email || !password) {
        setErrorMessage('Please fill all fields');
        setShowErrorModal(true);
        return;
      }
      
      const newUser = { 
        id: Date.now(), 
        name: name, 
        email: email, 
        password: password,
        isAdmin: email === 'pankuchauhan35@gmail.com' 
      };
      
      const updatedUsers = [...storedUsers, newUser];
      localStorage.setItem('app_users', JSON.stringify(updatedUsers));
      
      // Auto login after registration
      const loginUser = { id: newUser.id, name: newUser.name, email: newUser.email, isAdmin: newUser.isAdmin };
      localStorage.setItem('token', 'user-token-' + Date.now());
      localStorage.setItem('user', JSON.stringify(loginUser));
      setUser(loginUser);
      setShowLogin(false);
      setName('');
      setEmail('');
      setPassword('');
      showMessage('Registration successful! 🎉 Welcome to ShopHub!');
      showBrowserNotification(
        '🎉 Welcome to ShopHub!',
        `Thanks for joining ${name}! Get 10% off on your first order.`,
        'https://cdn-icons-png.flaticon.com/512/2838/2838912.png'
      );
      playNotificationSound();
    } else {
      // LOGIN - Check credentials
      const foundUser = storedUsers.find(u => u.email === email && u.password === password);
      
      if (foundUser) {
        const loginUser = { id: foundUser.id, name: foundUser.name, email: foundUser.email, isAdmin: foundUser.isAdmin };
        localStorage.setItem('token', 'user-token-' + Date.now());
        localStorage.setItem('user', JSON.stringify(loginUser));
        setUser(loginUser);
        setShowLogin(false);
        setEmail('');
        setPassword('');
        showMessage(`Welcome back, ${foundUser.name}! 👋`);
        showBrowserNotification(
          '👋 Welcome Back!',
          'Check out our new arrivals and exclusive offers!',
          'https://cdn-icons-png.flaticon.com/512/2838/2838912.png'
        );
        playNotificationSound();
      } else {
        setErrorMessage('Invalid email or password. Please check your credentials or register a new account.');
        setShowErrorModal(true);
      }
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    setUser(null);
    setCart([]);
    setWishlist([]);
    localStorage.removeItem('cart');
    showMessage('Logged out successfully 👋');
    showBrowserNotification(
      '👋 See you soon!',
      'Come back for more amazing deals and offers.',
      'https://cdn-icons-png.flaticon.com/512/190/190411.png'
    );
  };

  const addToCart = (product, quantity = 1) => {
    const existingItem = cart.find(item => item.id === product.id);
    let newCart;
    if (existingItem) {
      newCart = cart.map(item => 
        item.id === product.id ? { ...item, quantity: item.quantity + quantity } : item
      );
      setCart(newCart);
    } else {
      newCart = [...cart, { ...product, quantity: quantity }];
      setCart(newCart);
    }
    
    localStorage.setItem('cart', JSON.stringify(newCart));
    setCartReminder(false);
    
    showMessage(`${quantity} x ${product.name} added to cart! 🛒`);
    playNotificationSound();
    showBrowserNotification(
      '✨ Item Added to Cart!',
      `${product.name} x${quantity} - ${formatIndianRupee(product.price * quantity)}`,
      product.image
    );
  };

  const removeFromCart = (productId) => {
    const newCart = cart.filter(item => item.id !== productId);
    setCart(newCart);
    localStorage.setItem('cart', JSON.stringify(newCart));
    showMessage('Item removed from cart 🗑️');
  };

  const updateQuantity = (productId, newQuantity) => {
    if (newQuantity < 1) {
      removeFromCart(productId);
    } else {
      const updatedCart = cart.map(item =>
        item.id === productId ? { ...item, quantity: newQuantity } : item
      );
      setCart(updatedCart);
      localStorage.setItem('cart', JSON.stringify(updatedCart));
    }
  };

  const getCartTotal = () => {
    return cart.reduce((total, item) => total + (item.price * item.quantity), 0);
  };

  const getCartCount = () => {
    return cart.reduce((count, item) => count + item.quantity, 0);
  };

  const handleCheckoutInput = (e) => {
    setShippingDetails({
      ...shippingDetails,
      [e.target.name]: e.target.value
    });
  };

  // Buy Now - Direct purchase
  const buyNow = (product, quantity = 1) => {
    setCart([{ ...product, quantity: quantity }]);
    localStorage.setItem('cart', JSON.stringify([{ ...product, quantity: quantity }]));
    setShowProductDetail(false);
    
    if (!user) {
      setErrorMessage('Please login to place order');
      setShowErrorModal(true);
      return;
    }
    
    setShowCheckout(true);
    showMessage('Proceeding to checkout! 🚀');
  };

  // View Product Detail
  const viewProductDetail = (product) => {
    setSelectedProductDetail(product);
    setShowProductDetail(true);
  };

  const handlePaymentSuccess = () => {
    const orderDetails = {
      orderId: 'ORD' + Date.now(),
      items: [...cart],
      total: formatIndianRupee(getCartTotal()),
      paymentMethod: 'Online Payment (UPI/Card/QR)',
      shippingAddress: `${shippingDetails.fullName}, ${shippingDetails.address}, ${shippingDetails.city}, ${shippingDetails.state || 'N/A'} - ${shippingDetails.pincode}, Phone: ${shippingDetails.phone}`,
      date: new Date().toLocaleString()
    };
    
    const orders = JSON.parse(localStorage.getItem('orders') || '[]');
    orders.push({
      orderId: orderDetails.orderId,
      items: cart,
      total: getCartTotal(),
      shipping: shippingDetails,
      paymentMethod: 'Online Payment',
      status: 'Paid',
      date: new Date().toLocaleString(),
      userEmail: user?.email,
      userName: user?.name
    });
    localStorage.setItem('orders', JSON.stringify(orders));
    localStorage.removeItem('cart');
    
    setConfirmedOrder(orderDetails);
    setShowOrderConfirmation(true);
    setShowPayment(false);
    setCart([]);
    setShowCart(false);
    setShowCheckout(false);
    setShippingDetails({
      fullName: '', address: '', city: '', state: '', pincode: '', phone: '', paymentMethod: 'cod'
    });
    
    showBrowserNotification(
      '✅ Order Placed Successfully!',
      `Order #${orderDetails.orderId}\nTotal: ${orderDetails.total}`,
      'https://cdn-icons-png.flaticon.com/512/190/190411.png'
    );
    playNotificationSound();
  };

  const placeOrder = () => {
    if (!shippingDetails.fullName || !shippingDetails.address || !shippingDetails.city || 
        !shippingDetails.pincode || !shippingDetails.phone) {
      setErrorMessage('Please fill all shipping details');
      setShowErrorModal(true);
      return;
    }
    
    if (!user) {
      setErrorMessage('Please login to place order');
      setShowErrorModal(true);
      setShowCheckout(false);
      setShowLogin(true);
      return;
    }
    
    if (shippingDetails.paymentMethod === 'online') {
      setShowCheckout(false);
      setShowPayment(true);
      return;
    }
    
    const orderDetails = {
      orderId: 'ORD' + Date.now(),
      items: [...cart],
      total: formatIndianRupee(getCartTotal()),
      paymentMethod: 'Cash on Delivery',
      shippingAddress: `${shippingDetails.fullName}, ${shippingDetails.address}, ${shippingDetails.city}, ${shippingDetails.state || 'N/A'} - ${shippingDetails.pincode}, Phone: ${shippingDetails.phone}`,
      date: new Date().toLocaleString()
    };
    
    const orders = JSON.parse(localStorage.getItem('orders') || '[]');
    orders.push({
      orderId: orderDetails.orderId,
      items: cart,
      total: getCartTotal(),
      shipping: shippingDetails,
      paymentMethod: 'COD',
      status: 'Pending',
      date: new Date().toLocaleString(),
      userEmail: user?.email,
      userName: user?.name
    });
    localStorage.setItem('orders', JSON.stringify(orders));
    localStorage.removeItem('cart');
    
    setConfirmedOrder(orderDetails);
    setShowOrderConfirmation(true);
    setCart([]);
    setShowCart(false);
    setShowCheckout(false);
    setShippingDetails({
      fullName: '', address: '', city: '', state: '', pincode: '', phone: '', paymentMethod: 'cod'
    });
    
    showBrowserNotification(
      '✅ Order Placed Successfully!',
      `Order #${orderDetails.orderId}\nTotal: ${orderDetails.total}\nPayment: Cash on Delivery`,
      'https://cdn-icons-png.flaticon.com/512/190/190411.png'
    );
    playNotificationSound();
  };

  const filteredProducts = products.filter(product => {
    const matchesSearch = product.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = selectedCategory === 'All' || product.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  const categories = ['All', ...new Set(products.map(p => p.category))];

  if (showAdmin && user?.isAdmin) {
    return <AdminPanel onBack={() => setShowAdmin(false)} />;
  }

  return (
    <div className="app">
      {/* Product Detail Modal */}
      <ProductDetailModal 
        show={showProductDetail}
        onClose={() => setShowProductDetail(false)}
        product={selectedProductDetail}
        onAddToCart={addToCart}
        onBuyNow={buyNow}
      />

      {/* Order Confirmation Modal */}
      <OrderConfirmationModal 
        show={showOrderConfirmation}
        onClose={() => setShowOrderConfirmation(false)}
        orderDetails={confirmedOrder}
      />

      {/* Error Notification Modal */}
      <ErrorNotificationModal 
        show={showErrorModal}
        onClose={() => setShowErrorModal(false)}
        message={errorMessage}
        title="Alert"
      />

      {/* Toast Notification */}
      <div className="toast-container position-fixed bottom-0 end-0 p-3" style={{ zIndex: 1100 }}>
        <Toast show={showToast} onClose={() => setShowToast(false)} delay={4000} autohide bg="success">
          <Toast.Body className="text-white">{toastMessage}</Toast.Body>
        </Toast>
      </div>

      {/* Payment Modal */}
      <PaymentModal 
        show={showPayment}
        onClose={() => setShowPayment(false)}
        amount={getCartTotal()}
        onSuccess={handlePaymentSuccess}
      />

      {/* Promo Banner */}
      {showPromoBanner && (
        <div className="promo-banner py-2" style={{ background: 'linear-gradient(90deg, #ff6b6b, #feca57)' }}>
          <Container>
            <div className="d-flex justify-content-between align-items-center">
              <div className="text-dark">
                <i className="bi bi-megaphone-fill me-2"></i>
                <strong>🔥 NEW USER OFFER!</strong> Get 10% off on your first order | Free Shipping on ₹50,000+
              </div>
              <Button 
                variant="link" 
                className="text-dark p-0" 
                onClick={() => setShowPromoBanner(false)}
                style={{ textDecoration: 'none' }}
              >
                <i className="bi bi-x-lg"></i>
              </Button>
            </div>
          </Container>
        </div>
      )}

      {/* Navigation Bar */}
      <Navbar bg="dark" variant="dark" expand="lg" sticky="top" className="shadow">
        <Container>
          <Navbar.Brand href="#" className="d-flex align-items-center">
            <i className="bi bi-shop fs-3 me-2"></i>
            <span className="fw-bold fs-4">ShopHub India</span>
          </Navbar.Brand>
          <Navbar.Toggle aria-controls="basic-navbar-nav" />
          <Navbar.Collapse id="basic-navbar-nav">
            <Form className="mx-auto w-50">
              <InputGroup>
                <InputGroup.Text><i className="bi bi-search"></i></InputGroup.Text>
                <Form.Control
                  type="text"
                  placeholder="Search products..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </InputGroup>
            </Form>
            <Nav className="ms-auto align-items-center gap-2">
              <Button variant="outline-light" onClick={() => setShowWishlist(true)} className="position-relative">
                <i className="bi bi-heart"></i> Wishlist
                {wishlist.length > 0 && (
                  <Badge bg="danger" pill className="position-absolute top-0 start-100 translate-middle">
                    {wishlist.length}
                  </Badge>
                )}
              </Button>
              <Button variant="outline-light" onClick={() => setShowCart(true)} className="position-relative">
                <i className="bi bi-cart3"></i> Cart
                {getCartCount() > 0 && (
                  <Badge bg="warning" pill className="position-absolute top-0 start-100 translate-middle">
                    {getCartCount()}
                  </Badge>
                )}
              </Button>
              {user ? (
                <div className="d-flex gap-2 align-items-center">
                  <span className="text-light">
                    <i className="bi bi-person-circle"></i> {user.name}
                  </span>
                  {user.isAdmin && (
                    <Button variant="info" size="sm" onClick={() => setShowAdmin(true)}>
                      <i className="bi bi-speedometer2"></i> Admin
                    </Button>
                  )}
                  <Button variant="outline-danger" size="sm" onClick={handleLogout}>
                    <i className="bi bi-box-arrow-right"></i>
                  </Button>
                </div>
              ) : (
                <Button variant="primary" onClick={() => setShowLogin(true)}>
                  <i className="bi bi-person"></i> Login / Register
                </Button>
              )}
            </Nav>
          </Navbar.Collapse>
        </Container>
      </Navbar>

      {/* Category Filter */}
      <div className="category-bar bg-light py-3 border-bottom shadow-sm">
        <Container>
          <div className="d-flex gap-2 flex-wrap justify-content-center">
            {categories.map(category => (
              <Button
                key={category}
                variant={selectedCategory === category ? "primary" : "outline-secondary"}
                size="sm"
                onClick={() => setSelectedCategory(category)}
                className="rounded-pill px-3"
              >
                {category}
              </Button>
            ))}
          </div>
        </Container>
      </div>

      {/* Hero Banner */}
      <div className="hero-banner bg-primary text-white py-5 mb-4">
        <Container className="text-center">
          <h1 className="display-4 fw-bold mb-3">Welcome to ShopHub India</h1>
          <p className="lead mb-0">Create an account and get amazing deals!</p>
        </Container>
      </div>

      {/* Products Grid */}
      <Container className="py-4">
        <div className="d-flex justify-content-between align-items-center mb-4">
          <h3><i className="bi bi-grid-3x3-gap-fill me-2"></i>Featured Products</h3>
          <Badge bg="secondary" pill className="fs-6">{filteredProducts.length} products</Badge>
        </div>

        {loading ? (
          <div className="text-center py-5">
            <Spinner animation="border" variant="primary" />
            <p className="mt-3">Loading amazing products...</p>
          </div>
        ) : (
          <Row xs={1} sm={2} md={3} lg={4} className="g-4">
            {filteredProducts.map(product => (
              <Col key={product.id}>
                <div className="product-card">
                  <div className="image-wrapper position-relative" onClick={() => viewProductDetail(product)}>
                    <Card.Img variant="top" src={product.image} className="product-img" />
                    <Button 
                      variant={wishlist.some(item => item.id === product.id) ? "danger" : "light"}
                      size="sm"
                      className="wishlist-btn position-absolute top-0 end-0 m-2 rounded-circle"
                      onClick={(e) => {
                        e.stopPropagation();
                        toggleWishlist(product);
                      }}
                    >
                      <i className={`bi ${wishlist.some(item => item.id === product.id) ? 'bi-heart-fill' : 'bi-heart'}`}></i>
                    </Button>
                    {product.stock < 20 && (
                      <Badge bg="warning" className="stock-badge">Only {product.stock} left</Badge>
                    )}
                  </div>
                  <Card.Body className="d-flex flex-column" onClick={() => viewProductDetail(product)}>
                    <div className="d-flex justify-content-between align-items-start mb-2">
                      <Card.Title className="fs-6 fw-bold mb-0">{product.name}</Card.Title>
                      <Badge bg="info" pill>{product.brand}</Badge>
                    </div>
                    <Card.Text className="small text-muted">{product.description.substring(0, 60)}...</Card.Text>
                    <div className="rating mb-2">
                      {'★'.repeat(Math.floor(product.rating))}{'☆'.repeat(5 - Math.floor(product.rating))}
                      <span className="small text-muted ms-1">({product.rating})</span>
                      <Button variant="link" size="sm" className="p-0 ms-2" onClick={(e) => {
                        e.stopPropagation();
                        setSelectedProduct(product);
                        setShowReview(true);
                      }}>
                        <i className="bi bi-chat-dots"></i> Reviews
                      </Button>
                    </div>
                    <div className="mt-auto">
                      <div className="d-flex justify-content-between align-items-center">
                        <h5 className="text-primary mb-0 fw-bold">{formatIndianRupee(product.price)}</h5>
                        <Button 
                          variant="primary" 
                          size="sm" 
                          onClick={(e) => {
                            e.stopPropagation();
                            addToCart(product);
                          }} 
                          className="rounded-pill"
                        >
                          <i className="bi bi-cart-plus"></i> Add
                        </Button>
                      </div>
                    </div>
                  </Card.Body>
                </div>
              </Col>
            ))}
          </Row>
        )}
      </Container>

      {/* Wishlist Modal */}
      <Modal show={showWishlist} onHide={() => setShowWishlist(false)} size="lg" centered>
        <Modal.Header closeButton className="bg-danger text-white">
          <Modal.Title><i className="bi bi-heart-fill me-2"></i>My Wishlist ({wishlist.length})</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {wishlist.length === 0 ? (
            <div className="text-center py-5">
              <i className="bi bi-emoji-frown fs-1"></i>
              <p className="mt-3">Your wishlist is empty. Start adding items!</p>
            </div>
          ) : (
            <Row>
              {wishlist.map(product => (
                <Col md={6} key={product.id} className="mb-3">
                  <Card className="h-100">
                    <Row className="g-0">
                      <Col md={4}>
                        <Card.Img src={product.image} style={{ height: '100%', objectFit: 'cover' }} />
                      </Col>
                      <Col md={8}>
                        <Card.Body>
                          <Card.Title className="fs-6">{product.name}</Card.Title>
                          <Card.Text className="text-primary fw-bold">{formatIndianRupee(product.price)}</Card.Text>
                          <Button size="sm" variant="primary" onClick={() => addToCart(product)}>
                            <i className="bi bi-cart-plus"></i> Add to Cart
                          </Button>
                        </Card.Body>
                      </Col>
                    </Row>
                  </Card>
                </Col>
              ))}
            </Row>
          )}
        </Modal.Body>
      </Modal>

      {/* Review Modal */}
      <Modal show={showReview} onHide={() => setShowReview(false)} centered>
        <Modal.Header closeButton>
          <Modal.Title>Reviews for {selectedProduct?.name}</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <div className="mb-4">
            <h6>Write a Review</h6>
            <Form.Group className="mb-2">
              <Form.Select value={reviewRating} onChange={(e) => setReviewRating(parseInt(e.target.value))}>
                <option value={5}>★★★★★ (5)</option>
                <option value={4}>★★★★☆ (4)</option>
                <option value={3}>★★★☆☆ (3)</option>
                <option value={2}>★★☆☆☆ (2)</option>
                <option value={1}>★☆☆☆☆ (1)</option>
              </Form.Select>
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control as="textarea" rows={3} placeholder="Write your review..." value={reviewText} onChange={(e) => setReviewText(e.target.value)} />
            </Form.Group>
            <Button variant="primary" onClick={addReview}>Submit Review</Button>
          </div>
          <hr />
          <h6>Customer Reviews</h6>
          {getProductReviews(selectedProduct?.id).length === 0 ? (
            <p className="text-muted">No reviews yet. Be the first to review!</p>
          ) : (
            getProductReviews(selectedProduct?.id).map(review => (
              <div key={review.id} className="mb-3 p-2 bg-light rounded">
                <div className="fw-bold">{review.userName}</div>
                <div className="text-warning">{'★'.repeat(review.rating)}</div>
                <div className="small">{review.comment}</div>
                <div className="small text-muted">{new Date(review.date).toLocaleDateString()}</div>
              </div>
            ))
          )}
        </Modal.Body>
      </Modal>

      {/* Cart Modal */}
      <Modal show={showCart} onHide={() => setShowCart(false)} size="lg" centered>
        <Modal.Header closeButton className="bg-primary text-white">
          <Modal.Title><i className="bi bi-cart3 me-2"></i>Your Cart ({getCartCount()} items)</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {cart.length === 0 ? (
            <div className="text-center py-5">
              <i className="bi bi-emoji-smile fs-1 text-muted"></i>
              <p className="mt-3">Your cart is empty. Start shopping!</p>
            </div>
          ) : (
            <Table responsive>
              <thead>
                <tr><th>Product</th><th>Price</th><th>Qty</th><th>Total</th><th></th></tr>
              </thead>
              <tbody>
                {cart.map(item => (
                  <tr key={item.id}>
                    <td className="align-middle">
                      <div className="d-flex align-items-center gap-2">
                        <img src={item.image} alt={item.name} style={{ width: '50px', height: '50px', objectFit: 'cover' }} />
                        <span className="fw-bold">{item.name}</span>
                      </div>
                    </td>
                    <td className="align-middle">{formatIndianRupee(item.price)}</td>
                    <td className="align-middle">
                      <div className="d-flex gap-2">
                        <Button size="sm" variant="outline-secondary" onClick={() => updateQuantity(item.id, item.quantity - 1)}>-</Button>
                        <span className="fw-bold">{item.quantity}</span>
                        <Button size="sm" variant="outline-secondary" onClick={() => updateQuantity(item.id, item.quantity + 1)}>+</Button>
                      </div>
                    </td>
                    <td className="align-middle fw-bold">{formatIndianRupee(item.price * item.quantity)}</td>
                    <td className="align-middle">
                      <Button variant="link" className="text-danger" onClick={() => removeFromCart(item.id)}>
                        <i className="bi bi-trash"></i>
                      </Button>
                    </td>
                  </tr>
                ))}
              </tbody>
              <tfoot>
                <tr className="table-active">
                  <td colSpan="3" className="text-end fw-bold">Total:</td>
                  <td colSpan="2" className="fw-bold fs-5 text-primary">{formatIndianRupee(getCartTotal())}</td>
                </tr>
              </tfoot>
            </Table>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowCart(false)}>Continue Shopping</Button>
          {cart.length > 0 && (
            <Button variant="success" onClick={() => { setShowCart(false); setShowCheckout(true); }}>
              <i className="bi bi-credit-card"></i> Checkout
            </Button>
          )}
        </Modal.Footer>
      </Modal>

      {/* Checkout Modal */}
      <Modal show={showCheckout} onHide={() => setShowCheckout(false)} size="lg" centered>
        <Modal.Header closeButton className="bg-success text-white">
          <Modal.Title><i className="bi bi-clipboard-check me-2"></i>Checkout</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Row>
            <Col md={6}>
              <h5 className="mb-3">Order Summary</h5>
              <div className="bg-light p-3 rounded">
                {cart.map(item => (
                  <div key={item.id} className="d-flex justify-content-between mb-2">
                    <span>{item.name} x {item.quantity}</span>
                    <span>{formatIndianRupee(item.price * item.quantity)}</span>
                  </div>
                ))}
                <hr />
                <div className="d-flex justify-content-between fw-bold">
                  <span>Total:</span>
                  <span className="text-success">{formatIndianRupee(getCartTotal())}</span>
                </div>
              </div>
            </Col>
            <Col md={6}>
              <h5 className="mb-3">Shipping Details</h5>
              <Form>
                <Form.Control className="mb-2" type="text" name="fullName" placeholder="Full Name" value={shippingDetails.fullName} onChange={handleCheckoutInput} required />
                <Form.Control className="mb-2" type="text" name="address" placeholder="Address" value={shippingDetails.address} onChange={handleCheckoutInput} required />
                <Form.Control className="mb-2" type="text" name="city" placeholder="City" value={shippingDetails.city} onChange={handleCheckoutInput} required />
                <Form.Control className="mb-2" type="text" name="state" placeholder="State" value={shippingDetails.state} onChange={handleCheckoutInput} />
                <Form.Control className="mb-2" type="text" name="pincode" placeholder="PIN Code" value={shippingDetails.pincode} onChange={handleCheckoutInput} required />
                <Form.Control className="mb-2" type="tel" name="phone" placeholder="Phone" value={shippingDetails.phone} onChange={handleCheckoutInput} required />
                <Form.Select name="paymentMethod" value={shippingDetails.paymentMethod} onChange={handleCheckoutInput}>
                  <option value="cod">💰 Cash on Delivery</option>
                  <option value="online">💳 Online Payment (UPI / Card / QR)</option>
                </Form.Select>
              </Form>
            </Col>
          </Row>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowCheckout(false)}>Back</Button>
          <Button variant="success" onClick={placeOrder}>Place Order</Button>
        </Modal.Footer>
      </Modal>

      {/* Login/Register Modal - No Demo Account */}
      <Modal show={showLogin} onHide={() => setShowLogin(false)} centered>
        <Modal.Header closeButton className="bg-primary text-white">
          <Modal.Title><i className="bi bi-person-circle me-2"></i>{isLogin ? 'Login' : 'Create Account'}</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form onSubmit={handleLogin}>
            {!isLogin && (
              <Form.Control 
                className="mb-3" 
                type="text" 
                placeholder="Full Name" 
                value={name} 
                onChange={(e) => setName(e.target.value)} 
                required 
              />
            )}
            <Form.Control 
              className="mb-3" 
              type="email" 
              placeholder="Email Address" 
              value={email} 
              onChange={(e) => setEmail(e.target.value)} 
              required 
            />
            <Form.Control 
              className="mb-3" 
              type="password" 
              placeholder="Password" 
              value={password} 
              onChange={(e) => setPassword(e.target.value)} 
              required 
            />
            <Button type="submit" variant="primary" className="w-100">
              {isLogin ? 'Login' : 'Create Account'}
            </Button>
          </Form>
          <div className="text-center mt-3">
            <Button variant="link" onClick={() => setIsLogin(!isLogin)}>
              {isLogin ? "Don't have an account? Create one" : "Already have an account? Login"}
            </Button>
          </div>
          <Alert variant="info" className="mt-3 small">
            <i className="bi bi-shield-lock"></i> <strong>Secure Registration</strong><br />
            Create a free account to track orders, save wishlist, and get exclusive offers!
          </Alert>
        </Modal.Body>
      </Modal>

      {/* Floating WhatsApp Button */}
      <a
        href="https://wa.me/919876543210?text=Hi%20ShopHub%2C%20I%20need%20help%20with%20my%20order"
        target="_blank"
        rel="noopener noreferrer"
        className="whatsapp-float"
        style={{
          position: 'fixed',
          bottom: '80px',
          right: '20px',
          zIndex: 1000,
          backgroundColor: '#25D366',
          color: 'white',
          borderRadius: '50%',
          width: '55px',
          height: '55px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
          transition: 'transform 0.3s'
        }}
        onMouseEnter={(e) => e.target.style.transform = 'scale(1.1)'}
        onMouseLeave={(e) => e.target.style.transform = 'scale(1)'}
      >
        <i className="bi bi-whatsapp" style={{ fontSize: '30px' }}></i>
      </a>

      {/* Floating Cart Button */}
      {cart.length > 0 && (
        <button
          onClick={() => setShowCart(true)}
          className="cart-float"
          style={{
            position: 'fixed',
            bottom: '20px',
            right: '20px',
            zIndex: 1000,
            backgroundColor: '#1a1a2e',
            color: 'white',
            borderRadius: '50%',
            width: '55px',
            height: '55px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
            border: 'none',
            transition: 'transform 0.3s',
            animation: 'pulse 1.5s infinite'
          }}
          onMouseEnter={(e) => e.target.style.transform = 'scale(1.1)'}
          onMouseLeave={(e) => e.target.style.transform = 'scale(1)'}
        >
          <i className="bi bi-cart3" style={{ fontSize: '24px' }}></i>
          <span style={{
            position: 'absolute',
            top: '-5px',
            right: '-5px',
            backgroundColor: '#ff6b6b',
            borderRadius: '50%',
            width: '20px',
            height: '20px',
            fontSize: '11px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center'
          }}>
            {getCartCount()}
          </span>
        </button>
      )}

      {/* Footer */}
      <footer className="bg-dark text-white mt-5 py-4">
        <Container>
          <Row>
            <Col md={4}>
              <h5><i className="bi bi-shop"></i> ShopHub India</h5>
              <p className="small">Your one-stop destination for quality products.</p>
            </Col>
            <Col md={4}>
              <h5>Quick Links</h5>
              <ul className="list-unstyled small">
                <li><a href="#" className="text-white-50 text-decoration-none">About Us</a></li>
                <li><a href="#" className="text-white-50 text-decoration-none">Contact</a></li>
                <li><a href="#" className="text-white-50 text-decoration-none">Returns</a></li>
              </ul>
            </Col>
            <Col md={4}>
              <h5>Contact</h5>
              <p className="small mb-1"><i className="bi bi-envelope"></i> support@shophub.com</p>
              <p className="small"><i className="bi bi-telephone"></i> +91 98765 43210</p>
            </Col>
          </Row>
          <hr />
          <p className="text-center small mb-0">&copy; 2025 ShopHub India. All rights reserved.</p>
        </Container>
      </footer>
    </div>
  );
}

export default App;
